/* From Uiverse.io by kamehame-ha - Tags: simple, animated, clean, sample */
.__UIV_SCOPE__ .cards {
  display: flex;
  flex-direction: column;
  gap: 15px;
}

.__UIV_SCOPE__ .cards .red {
  background-color: #f43f5e;
}

.__UIV_SCOPE__ .cards .blue {
  background-color: #3b82f6;
}

.__UIV_SCOPE__ .cards .green {
  background-color: #22c55e;
}

.__UIV_SCOPE__ .cards .card {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  text-align: center;
  height: 100px;
  width: 250px;
  border-radius: 10px;
  color: white;
  cursor: pointer;
  transition: 400ms;
}

.__UIV_SCOPE__ .cards .card p.tip {
  font-size: 1em;
  font-weight: 700;
}

.__UIV_SCOPE__ .cards .card p.second-text {
  font-size: .7em;
}

.__UIV_SCOPE__ .cards .card:hover {
  transform: scale(1.1, 1.1);
}

.__UIV_SCOPE__ .cards:hover > .card:not(:hover) {
  filter: blur(10px);
  transform: scale(0.9, 0.9);
}
